-- =====================================================================
-- QR Payment System - initial schema
-- Money is stored as BIGINT minor units (paise). Never float/double.
-- Primary keys are UUIDv7 generated by the application (time-ordered,
-- so B-tree inserts stay append-mostly like a sequence).
-- =====================================================================

CREATE TABLE users (
    id              UUID PRIMARY KEY,
    email           VARCHAR(255) NOT NULL,
    password_hash   VARCHAR(100) NOT NULL,
    full_name       VARCHAR(120) NOT NULL,
    role            VARCHAR(20)  NOT NULL CHECK (role IN ('CUSTOMER', 'MERCHANT')),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX ux_users_email ON users (lower(email));

CREATE TABLE merchants (
    id              UUID PRIMARY KEY,
    user_id         UUID         NOT NULL UNIQUE REFERENCES users (id),
    business_name   VARCHAR(120) NOT NULL,
    vpa             VARCHAR(80)  NOT NULL UNIQUE,          -- payment handle, e.g. chai-point-8f2a@qrpay
    category_code   VARCHAR(4)   NOT NULL,                 -- ISO 18245 merchant category code
    webhook_url     VARCHAR(500),
    webhook_secret  VARCHAR(64)  NOT NULL,
    status          VARCHAR(20)  NOT NULL CHECK (status IN ('ACTIVE', 'SUSPENDED')),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- One wallet per owner per currency. SYSTEM wallets represent money that
-- enters/leaves the closed loop (bank settlement account) and may go negative,
-- which keeps SUM(balance) over all wallets == 0 (double-entry invariant).
CREATE TABLE wallets (
    id              UUID PRIMARY KEY,
    owner_id        UUID        NOT NULL,
    owner_type      VARCHAR(20) NOT NULL CHECK (owner_type IN ('USER', 'MERCHANT', 'SYSTEM')),
    balance         BIGINT      NOT NULL,
    currency        VARCHAR(3)  NOT NULL,
    pin_hash        VARCHAR(100),
    version         BIGINT      NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ux_wallet_owner UNIQUE (owner_type, owner_id, currency),
    CONSTRAINT ck_wallet_non_negative CHECK (balance >= 0 OR owner_type = 'SYSTEM')
);

CREATE TABLE qr_codes (
    id              UUID PRIMARY KEY,
    merchant_id     UUID        NOT NULL REFERENCES merchants (id),
    type            VARCHAR(10) NOT NULL CHECK (type IN ('STATIC', 'DYNAMIC')),
    amount          BIGINT CHECK (amount IS NULL OR amount > 0),
    currency        VARCHAR(3)  NOT NULL,
    order_ref       VARCHAR(64),
    status          VARCHAR(20) NOT NULL CHECK (status IN ('ACTIVE', 'PAID', 'EXPIRED', 'DISABLED')),
    payload         TEXT        NOT NULL,
    expires_at      TIMESTAMPTZ,
    paid_payment_id UUID,
    version         BIGINT      NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT ck_dynamic_has_amount CHECK (type = 'STATIC' OR (amount IS NOT NULL AND expires_at IS NOT NULL))
);
-- exactly one static QR per merchant
CREATE UNIQUE INDEX ux_qr_static_per_merchant ON qr_codes (merchant_id) WHERE type = 'STATIC';
-- merchant order reference is unique per merchant (lets merchants retry QR creation safely)
CREATE UNIQUE INDEX ux_qr_order_ref ON qr_codes (merchant_id, order_ref) WHERE order_ref IS NOT NULL;
-- expiry sweeper only scans live dynamic codes
CREATE INDEX ix_qr_active_expiry ON qr_codes (expires_at) WHERE status = 'ACTIVE' AND type = 'DYNAMIC';

CREATE TABLE payments (
    id              UUID PRIMARY KEY,
    qr_id           UUID         NOT NULL REFERENCES qr_codes (id),
    qr_type         VARCHAR(10)  NOT NULL CHECK (qr_type IN ('STATIC', 'DYNAMIC')),
    merchant_id     UUID         NOT NULL REFERENCES merchants (id),
    merchant_name   VARCHAR(120) NOT NULL,
    payer_user_id   UUID         NOT NULL REFERENCES users (id),
    payer_name      VARCHAR(120) NOT NULL,
    amount          BIGINT       NOT NULL CHECK (amount > 0),
    currency        VARCHAR(3)   NOT NULL,
    status          VARCHAR(20)  NOT NULL CHECK (status IN ('CREATED', 'SUCCESS', 'FAILED', 'EXPIRED', 'CANCELLED')),
    failure_reason  VARCHAR(64),
    order_ref       VARCHAR(64),
    note            VARCHAR(140),
    idempotency_key VARCHAR(64)  NOT NULL,
    expires_at      TIMESTAMPTZ  NOT NULL,
    completed_at    TIMESTAMPTZ,
    version         BIGINT       NOT NULL DEFAULT 0,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- durable idempotency guard (Redis is the fast path, this is the backstop)
    CONSTRAINT ux_payment_idempotency UNIQUE (payer_user_id, idempotency_key)
);
CREATE INDEX ix_payments_merchant_created ON payments (merchant_id, created_at DESC);
CREATE INDEX ix_payments_payer_created ON payments (payer_user_id, created_at DESC);
CREATE INDEX ix_payments_qr ON payments (qr_id);
CREATE INDEX ix_payments_pending_expiry ON payments (expires_at) WHERE status = 'CREATED';
-- a dynamic QR can be settled by at most one successful payment (last line of defence
-- behind the Redis lock and the conditional ACTIVE->PAID update on qr_codes)
CREATE UNIQUE INDEX ux_payment_success_per_dynamic_qr ON payments (qr_id)
    WHERE status = 'SUCCESS' AND qr_type = 'DYNAMIC';

-- Immutable, append-only double-entry ledger. Every transfer writes one DEBIT
-- and one CREDIT with the same amount. Balances can always be rebuilt from here.
CREATE TABLE ledger_entries (
    id              UUID PRIMARY KEY,
    wallet_id       UUID         NOT NULL REFERENCES wallets (id),
    transfer_id     UUID         NOT NULL,                  -- groups the debit/credit pair
    payment_id      UUID REFERENCES payments (id),          -- null for top-ups
    entry_type      VARCHAR(10)  NOT NULL CHECK (entry_type IN ('DEBIT', 'CREDIT')),
    amount          BIGINT       NOT NULL CHECK (amount > 0),
    balance_after   BIGINT       NOT NULL,
    description     VARCHAR(140),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX ix_ledger_wallet_created ON ledger_entries (wallet_id, created_at DESC);
CREATE INDEX ix_ledger_transfer ON ledger_entries (transfer_id);

-- Transactional outbox: events are written in the SAME DB transaction as the
-- state change, then relayed to Kafka asynchronously (no dual-write problem).
CREATE TABLE outbox_events (
    id              UUID PRIMARY KEY,
    aggregate_type  VARCHAR(40)  NOT NULL,
    aggregate_id    UUID         NOT NULL,
    event_type      VARCHAR(60)  NOT NULL,
    topic           VARCHAR(120) NOT NULL,
    partition_key   VARCHAR(80)  NOT NULL,
    payload         TEXT         NOT NULL,
    status          VARCHAR(20)  NOT NULL CHECK (status IN ('PENDING', 'PUBLISHED')),
    attempts        INT          NOT NULL DEFAULT 0,
    last_error      VARCHAR(500),
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    published_at    TIMESTAMPTZ
);
CREATE INDEX ix_outbox_pending ON outbox_events (created_at) WHERE status = 'PENDING';
CREATE INDEX ix_outbox_published ON outbox_events (published_at) WHERE status = 'PUBLISHED';

-- The closed-loop system settlement wallet (source of top-ups / signup bonus).
